/*
    University Relational Database Setup
    ====================================

    Creates a normalized relational counterpart to UniversityDocumentDB and
    loads the same university, college, department, program, and course data.

    Child identifiers repeat beneath different parents in the source documents,
    so each child table uses a hierarchical composite primary key. Every foreign
    key column has the same name as the primary key column it references.
*/

USE master;
GO

IF DB_ID(N'UniversityRelationalDB') IS NOT NULL
BEGIN
    ALTER DATABASE UniversityRelationalDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE UniversityRelationalDB;
END
GO

CREATE DATABASE UniversityRelationalDB;
GO

USE UniversityRelationalDB;
GO

CREATE TABLE dbo.University
(
    UniversityId INT NOT NULL,
    UniversityName NVARCHAR(100) NOT NULL,
    Status VARCHAR(20) NOT NULL,
    FoundedYear SMALLINT NOT NULL,
    StudentPopulation INT NOT NULL,
    Website NVARCHAR(255) NOT NULL,
    City NVARCHAR(100) NOT NULL,
    State CHAR(2) NOT NULL,
    Country NVARCHAR(100) NOT NULL,
    CONSTRAINT PK_University PRIMARY KEY (UniversityId),
    CONSTRAINT CK_University_Status
        CHECK (Status IN ('active', 'inactive', 'planning')),
    CONSTRAINT CK_University_FoundedYear
        CHECK (FoundedYear BETWEEN 1000 AND 9999),
    CONSTRAINT CK_University_StudentPopulation
        CHECK (StudentPopulation >= 0)
);
GO

CREATE TABLE dbo.College
(
    UniversityId INT NOT NULL,
    CollegeId INT NOT NULL,
    CollegeName NVARCHAR(100) NOT NULL,
    DeanName NVARCHAR(100) NOT NULL,
    CONSTRAINT PK_College PRIMARY KEY (UniversityId, CollegeId),
    CONSTRAINT FK_College_University FOREIGN KEY (UniversityId)
        REFERENCES dbo.University (UniversityId)
        ON DELETE CASCADE
);
GO

CREATE TABLE dbo.Department
(
    UniversityId INT NOT NULL,
    CollegeId INT NOT NULL,
    DepartmentId INT NOT NULL,
    DepartmentName NVARCHAR(100) NOT NULL,
    ChairName NVARCHAR(100) NOT NULL,
    CONSTRAINT PK_Department
        PRIMARY KEY (UniversityId, CollegeId, DepartmentId),
    CONSTRAINT FK_Department_College
        FOREIGN KEY (UniversityId, CollegeId)
        REFERENCES dbo.College (UniversityId, CollegeId)
        ON DELETE CASCADE
);
GO

CREATE TABLE dbo.Program
(
    UniversityId INT NOT NULL,
    CollegeId INT NOT NULL,
    DepartmentId INT NOT NULL,
    ProgramId INT NOT NULL,
    ProgramName NVARCHAR(100) NOT NULL,
    DegreeType VARCHAR(20) NOT NULL,
    DeliveryMode VARCHAR(20) NOT NULL,
    CONSTRAINT PK_Program
        PRIMARY KEY (UniversityId, CollegeId, DepartmentId, ProgramId),
    CONSTRAINT FK_Program_Department
        FOREIGN KEY (UniversityId, CollegeId, DepartmentId)
        REFERENCES dbo.Department (UniversityId, CollegeId, DepartmentId)
        ON DELETE CASCADE,
    CONSTRAINT CK_Program_DegreeType
        CHECK (DegreeType IN ('Bachelor', 'Master', 'Doctorate')),
    CONSTRAINT CK_Program_DeliveryMode
        CHECK (DeliveryMode IN ('On-campus', 'Hybrid', 'Online'))
);
GO

CREATE TABLE dbo.Course
(
    UniversityId INT NOT NULL,
    CollegeId INT NOT NULL,
    DepartmentId INT NOT NULL,
    ProgramId INT NOT NULL,
    CourseCode VARCHAR(20) NOT NULL,
    CourseName NVARCHAR(100) NOT NULL,
    Credits TINYINT NOT NULL,
    CourseType VARCHAR(20) NOT NULL,
    CONSTRAINT PK_Course
        PRIMARY KEY
        (
            UniversityId,
            CollegeId,
            DepartmentId,
            ProgramId,
            CourseCode
        ),
    CONSTRAINT FK_Course_Program
        FOREIGN KEY (UniversityId, CollegeId, DepartmentId, ProgramId)
        REFERENCES dbo.Program
            (UniversityId, CollegeId, DepartmentId, ProgramId)
        ON DELETE CASCADE,
    CONSTRAINT CK_Course_Credits CHECK (Credits BETWEEN 1 AND 30),
    CONSTRAINT CK_Course_CourseType
        CHECK (CourseType IN ('core', 'elective'))
);
GO

