-- Verify that the relational row counts match the source document hierarchy.
SELECT
    EntityName,
    ExpectedRows,
    ActualRows,
    CASE WHEN ExpectedRows = ActualRows THEN 'PASS' ELSE 'FAIL' END AS Result
FROM
(
    SELECT 'University' AS EntityName, 50 AS ExpectedRows,
        (SELECT COUNT(*) FROM dbo.University) AS ActualRows
    UNION ALL
    SELECT 'College', 149, (SELECT COUNT(*) FROM dbo.College)
    UNION ALL
    SELECT 'Department', 364, (SELECT COUNT(*) FROM dbo.Department)
    UNION ALL
    SELECT 'Program', 910, (SELECT COUNT(*) FROM dbo.Program)
    UNION ALL
    SELECT 'Course', 2746, (SELECT COUNT(*) FROM dbo.Course)
) AS Verification
ORDER BY
    CASE EntityName
        WHEN 'University' THEN 1
        WHEN 'College' THEN 2
        WHEN 'Department' THEN 3
        WHEN 'Program' THEN 4
        WHEN 'Course' THEN 5
    END;
GO

/*
    Relational equivalents for the 20 UniversityDocumentDB operations
    ------------------------------------------------------------------
*/

-- Operation 1: List university name, city, and state.
SELECT UniversityName, City, State
FROM dbo.University
ORDER BY UniversityName;
GO

-- Operation 2: Find universities located in California.
SELECT UniversityName, City
FROM dbo.University
WHERE State = 'CA'
ORDER BY UniversityName;
GO

-- Operation 3: Retrieve the first college name for every university.
SELECT u.UniversityName, firstCollege.CollegeName
FROM dbo.University AS u
OUTER APPLY
(
    SELECT TOP (1) c.CollegeName
    FROM dbo.College AS c
    WHERE c.UniversityId = u.UniversityId
    ORDER BY c.CollegeId
) AS firstCollege
ORDER BY u.UniversityName;
GO

-- Operation 4: Show every college name across all universities.
SELECT u.UniversityName, c.CollegeName
FROM dbo.University AS u
INNER JOIN dbo.College AS c
    ON c.UniversityId = u.UniversityId
ORDER BY u.UniversityName, c.CollegeId;
GO

-- Operation 5: Count colleges per university.
SELECT u.UniversityId, u.UniversityName, COUNT(c.CollegeId) AS CollegeCount
FROM dbo.University AS u
LEFT JOIN dbo.College AS c
    ON c.UniversityId = u.UniversityId
GROUP BY u.UniversityId, u.UniversityName
ORDER BY CollegeCount DESC, u.UniversityName;
GO

-- Operation 6: Display dean names for a selected college and university.
DECLARE @Operation6UniversityId INT = 1001;
DECLARE @Operation6CollegeId INT = 1;

SELECT u.UniversityName, c.CollegeName, c.DeanName
FROM dbo.University AS u
INNER JOIN dbo.College AS c
    ON c.UniversityId = u.UniversityId
WHERE c.UniversityId = @Operation6UniversityId
  AND c.CollegeId = @Operation6CollegeId;
GO

-- Operation 7: List departments for a selected university and college.
DECLARE @Operation7UniversityId INT = 1001;
DECLARE @Operation7CollegeId INT = 1;

SELECT d.DepartmentId, d.DepartmentName
FROM dbo.Department AS d
WHERE d.UniversityId = @Operation7UniversityId
  AND d.CollegeId = @Operation7CollegeId
ORDER BY d.DepartmentId;
GO

-- Operation 8: Find a department by name and return its chair.
DECLARE @Operation8DepartmentName NVARCHAR(100) = N'Computer Science';

SELECT
    u.UniversityName,
    c.CollegeName,
    d.DepartmentName,
    d.ChairName
FROM dbo.Department AS d
INNER JOIN dbo.College AS c
    ON c.UniversityId = d.UniversityId
   AND c.CollegeId = d.CollegeId
INNER JOIN dbo.University AS u
    ON u.UniversityId = d.UniversityId
WHERE d.DepartmentName = @Operation8DepartmentName
ORDER BY u.UniversityName, c.CollegeName;
GO

-- Operation 9: Return programs for a selected department.
DECLARE @Operation9UniversityId INT = 1001;
DECLARE @Operation9CollegeId INT = 1;
DECLARE @Operation9DepartmentId INT = 110;

SELECT ProgramId, ProgramName, DegreeType, DeliveryMode
FROM dbo.Program
WHERE UniversityId = @Operation9UniversityId
  AND CollegeId = @Operation9CollegeId
  AND DepartmentId = @Operation9DepartmentId
ORDER BY ProgramId;
GO

-- Operation 10: Display course codes in a selected program.
DECLARE @Operation10UniversityId INT = 1001;
DECLARE @Operation10CollegeId INT = 1;
DECLARE @Operation10DepartmentId INT = 110;
DECLARE @Operation10ProgramId INT = 660;

SELECT CourseCode, CourseName
FROM dbo.Course
WHERE UniversityId = @Operation10UniversityId
  AND CollegeId = @Operation10CollegeId
  AND DepartmentId = @Operation10DepartmentId
  AND ProgramId = @Operation10ProgramId
ORDER BY CourseCode;
GO

-- Operation 11: Find universities with hybrid or online programs.
SELECT u.UniversityId, u.UniversityName
FROM dbo.University AS u
WHERE EXISTS
(
    SELECT 1
    FROM dbo.Program AS p
    WHERE p.UniversityId = u.UniversityId
      AND p.DeliveryMode IN ('Hybrid', 'Online')
)
ORDER BY u.UniversityName;
GO

-- Operation 12: Find universities founded before 1950.
SELECT UniversityId, UniversityName, FoundedYear
FROM dbo.University
WHERE FoundedYear < 1950
ORDER BY FoundedYear, UniversityName;
GO

-- Operation 13: Find universities with more than 30,000 students.
SELECT UniversityId, UniversityName, StudentPopulation
FROM dbo.University
WHERE StudentPopulation > 30000
ORDER BY StudentPopulation DESC, UniversityName;
GO

-- Operation 14: Return a complete college hierarchy as rectangular rows.
DECLARE @Operation14UniversityId INT = 1001;
DECLARE @Operation14CollegeId INT = 1;

SELECT
    u.UniversityId,
    u.UniversityName,
    c.CollegeId,
    c.CollegeName,
    c.DeanName,
    d.DepartmentId,
    d.DepartmentName,
    d.ChairName,
    p.ProgramId,
    p.ProgramName,
    p.DegreeType,
    p.DeliveryMode,
    cr.CourseCode,
    cr.CourseName,
    cr.Credits,
    cr.CourseType
FROM dbo.University AS u
INNER JOIN dbo.College AS c
    ON c.UniversityId = u.UniversityId
LEFT JOIN dbo.Department AS d
    ON d.UniversityId = c.UniversityId
   AND d.CollegeId = c.CollegeId
LEFT JOIN dbo.Program AS p
    ON p.UniversityId = d.UniversityId
   AND p.CollegeId = d.CollegeId
   AND p.DepartmentId = d.DepartmentId
LEFT JOIN dbo.Course AS cr
    ON cr.UniversityId = p.UniversityId
   AND cr.CollegeId = p.CollegeId
   AND cr.DepartmentId = p.DepartmentId
   AND cr.ProgramId = p.ProgramId
WHERE c.UniversityId = @Operation14UniversityId
  AND c.CollegeId = @Operation14CollegeId
ORDER BY d.DepartmentId, p.ProgramId, cr.CourseCode;
GO

-- Operation 15: Show programs for a selected college and department.
DECLARE @Operation15UniversityId INT = 1001;
DECLARE @Operation15CollegeId INT = 1;
DECLARE @Operation15DepartmentId INT = 110;

SELECT
    c.CollegeName,
    d.DepartmentName,
    p.ProgramId,
    p.ProgramName,
    p.DegreeType,
    p.DeliveryMode
FROM dbo.College AS c
INNER JOIN dbo.Department AS d
    ON d.UniversityId = c.UniversityId
   AND d.CollegeId = c.CollegeId
INNER JOIN dbo.Program AS p
    ON p.UniversityId = d.UniversityId
   AND p.CollegeId = d.CollegeId
   AND p.DepartmentId = d.DepartmentId
WHERE p.UniversityId = @Operation15UniversityId
  AND p.CollegeId = @Operation15CollegeId
  AND p.DepartmentId = @Operation15DepartmentId
ORDER BY p.ProgramId;
GO

-- Operation 16: Check whether a course code exists anywhere.
DECLARE @Operation16CourseCode VARCHAR(20) = 'COM11';

SELECT
    CASE
        WHEN EXISTS
        (
            SELECT 1
            FROM dbo.Course
            WHERE CourseCode = @Operation16CourseCode
        )
        THEN CAST(1 AS BIT)
        ELSE CAST(0 AS BIT)
    END AS CourseCodeExists;
GO

-- Operation 17: Add a college and show the before/after state.
BEGIN TRANSACTION;

DECLARE @Operation17UniversityId INT = 1001;
DECLARE @Operation17CollegeId INT = 99;

SELECT 'Before' AS State, c.*
FROM dbo.College AS c
WHERE c.UniversityId = @Operation17UniversityId
  AND c.CollegeId = @Operation17CollegeId;

INSERT INTO dbo.College
    (UniversityId, CollegeId, CollegeName, DeanName)
VALUES
    (@Operation17UniversityId, @Operation17CollegeId,
     N'College of Public Health', N'Dr. Jordan Lee');

SELECT 'After' AS State, c.*
FROM dbo.College AS c
WHERE c.UniversityId = @Operation17UniversityId
  AND c.CollegeId = @Operation17CollegeId;

ROLLBACK TRANSACTION;
GO

-- Operation 18: Update a website and show the before/after state.
BEGIN TRANSACTION;

DECLARE @Operation18UniversityId INT = 1001;

SELECT 'Before' AS State, UniversityId, UniversityName, Website
FROM dbo.University
WHERE UniversityId = @Operation18UniversityId;

UPDATE dbo.University
SET Website = N'https://www.riverside.example.edu'
WHERE UniversityId = @Operation18UniversityId;

SELECT 'After' AS State, UniversityId, UniversityName, Website
FROM dbo.University
WHERE UniversityId = @Operation18UniversityId;

ROLLBACK TRANSACTION;
GO

-- Operation 19: Add a course to a program and show before/after state.
BEGIN TRANSACTION;

DECLARE @Operation19UniversityId INT = 1001;
DECLARE @Operation19CollegeId INT = 1;
DECLARE @Operation19DepartmentId INT = 110;
DECLARE @Operation19ProgramId INT = 660;
DECLARE @Operation19CourseCode VARCHAR(20) = 'NEW99';

SELECT 'Before' AS State, cr.*
FROM dbo.Course AS cr
WHERE cr.UniversityId = @Operation19UniversityId
  AND cr.CollegeId = @Operation19CollegeId
  AND cr.DepartmentId = @Operation19DepartmentId
  AND cr.ProgramId = @Operation19ProgramId
  AND cr.CourseCode = @Operation19CourseCode;

INSERT INTO dbo.Course
(
    UniversityId,
    CollegeId,
    DepartmentId,
    ProgramId,
    CourseCode,
    CourseName,
    Credits,
    CourseType
)
VALUES
(
    @Operation19UniversityId,
    @Operation19CollegeId,
    @Operation19DepartmentId,
    @Operation19ProgramId,
    @Operation19CourseCode,
    N'Relational Database Design',
    3,
    'elective'
);

SELECT 'After' AS State, cr.*
FROM dbo.Course AS cr
WHERE cr.UniversityId = @Operation19UniversityId
  AND cr.CollegeId = @Operation19CollegeId
  AND cr.DepartmentId = @Operation19DepartmentId
  AND cr.ProgramId = @Operation19ProgramId
  AND cr.CourseCode = @Operation19CourseCode;

ROLLBACK TRANSACTION;
GO

-- Operation 20: Remove a department and show the before/after state.
BEGIN TRANSACTION;

DECLARE @Operation20UniversityId INT = 1001;
DECLARE @Operation20CollegeId INT = 1;
DECLARE @Operation20DepartmentId INT = 111;

SELECT
    'Before' AS State,
    d.UniversityId,
    d.CollegeId,
    d.DepartmentId,
    d.DepartmentName
FROM dbo.Department AS d
WHERE d.UniversityId = @Operation20UniversityId
  AND d.CollegeId = @Operation20CollegeId
  AND d.DepartmentId = @Operation20DepartmentId;

DELETE FROM dbo.Department
WHERE UniversityId = @Operation20UniversityId
  AND CollegeId = @Operation20CollegeId
  AND DepartmentId = @Operation20DepartmentId;

SELECT
    'After' AS State,
    d.UniversityId,
    d.CollegeId,
    d.DepartmentId,
    d.DepartmentName
FROM dbo.Department AS d
WHERE d.UniversityId = @Operation20UniversityId
  AND d.CollegeId = @Operation20CollegeId
  AND d.DepartmentId = @Operation20DepartmentId;

ROLLBACK TRANSACTION;
GO
